create or replace function public.is_tour_organiser(target_tour uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.tours t where t.id=target_tour and t.organiser_user_id=(select auth.uid())); $$;
create or replace function public.is_tour_player(target_tour uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.tour_players tp where tp.tour_id=target_tour and tp.user_id=(select auth.uid()) and tp.status<>'withdrawn'); $$;
create or replace function public.match_tour(target_match uuid) returns uuid language sql stable security definer set search_path=public as $$ select r.tour_id from public.matches m join public.rounds r on r.id=m.round_id where m.id=target_match; $$;
create or replace function public.is_match_participant(target_match uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.match_participants mp join public.tour_players tp on tp.id=mp.tour_player_id where mp.match_id=target_match and tp.user_id=(select auth.uid())); $$;
create or replace function public.can_read_tour(target_tour uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_tour_organiser(target_tour) or public.is_tour_player(target_tour) or exists(select 1 from public.tours t where t.id=target_tour and t.spectator_enabled); $$;
revoke all on function public.is_tour_organiser(uuid),public.is_tour_player(uuid),public.match_tour(uuid),public.is_match_participant(uuid),public.can_read_tour(uuid) from public; grant execute on function public.is_tour_organiser(uuid),public.is_tour_player(uuid),public.match_tour(uuid),public.is_match_participant(uuid),public.can_read_tour(uuid) to anon,authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','tours','teams','tour_players','courses','course_tees','course_holes','rounds','round_course_snapshots','round_hole_snapshots','round_players','matches','match_participants','match_handicaps','hole_scores','team_hole_scores','selected_drives','alternate_shot_settings','match_confirmations','invitations','audit_log'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy profiles_self_select on public.profiles for select to authenticated using(id=(select auth.uid())); create policy profiles_self_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy courses_authenticated_read on public.courses for select to authenticated using(true); create policy tees_authenticated_read on public.course_tees for select to authenticated using(true); create policy holes_authenticated_read on public.course_holes for select to authenticated using(true);
create policy tours_member_read on public.tours for select to authenticated using(public.can_read_tour(id)); create policy tours_public_read on public.tours for select to anon using(spectator_enabled); create policy tours_organiser_insert on public.tours for insert to authenticated with check(organiser_user_id=(select auth.uid())); create policy tours_organiser_update on public.tours for update to authenticated using(public.is_tour_organiser(id)) with check(organiser_user_id=(select auth.uid())); create policy tours_organiser_delete on public.tours for delete to authenticated using(public.is_tour_organiser(id));
create policy teams_read on public.teams for select to authenticated using(public.can_read_tour(tour_id)); create policy teams_public_read on public.teams for select to anon using(exists(select 1 from public.tours t where t.id=tour_id and t.spectator_enabled)); create policy teams_org_all on public.teams for all to authenticated using(public.is_tour_organiser(tour_id)) with check(public.is_tour_organiser(tour_id));
create policy tour_players_read on public.tour_players for select to authenticated using(public.can_read_tour(tour_id)); create policy tour_players_public_read on public.tour_players for select to anon using(exists(select 1 from public.tours t where t.id=tour_id and t.spectator_enabled)); create policy tour_players_org_all on public.tour_players for all to authenticated using(public.is_tour_organiser(tour_id)) with check(public.is_tour_organiser(tour_id));
create policy rounds_read on public.rounds for select to authenticated using(public.can_read_tour(tour_id)); create policy rounds_public_read on public.rounds for select to anon using(exists(select 1 from public.tours t where t.id=tour_id and t.spectator_enabled)); create policy rounds_org_all on public.rounds for all to authenticated using(public.is_tour_organiser(tour_id)) with check(public.is_tour_organiser(tour_id));
create policy matches_read on public.matches for select to authenticated using(public.can_read_tour((select r.tour_id from public.rounds r where r.id=round_id))); create policy matches_org_all on public.matches for all to authenticated using(public.is_tour_organiser((select r.tour_id from public.rounds r where r.id=round_id))) with check(public.is_tour_organiser((select r.tour_id from public.rounds r where r.id=round_id)));
create policy match_participants_read on public.match_participants for select to authenticated using(public.can_read_tour(public.match_tour(match_id))); create policy match_participants_org_all on public.match_participants for all to authenticated using(public.is_tour_organiser(public.match_tour(match_id))) with check(public.is_tour_organiser(public.match_tour(match_id)));
create policy hole_scores_read on public.hole_scores for select to authenticated using(public.can_read_tour(public.match_tour(match_id))); create policy hole_scores_insert on public.hole_scores for insert to authenticated with check(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)); create policy hole_scores_update on public.hole_scores for update to authenticated using(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)) with check(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)); create policy hole_scores_delete on public.hole_scores for delete to authenticated using(public.is_tour_organiser(public.match_tour(match_id)));
create policy team_scores_read on public.team_hole_scores for select to authenticated using(public.can_read_tour(public.match_tour(match_id))); create policy team_scores_insert on public.team_hole_scores for insert to authenticated with check(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)); create policy team_scores_update on public.team_hole_scores for update to authenticated using(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)) with check(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id));
create policy selected_drives_read on public.selected_drives for select to authenticated using(public.can_read_tour(public.match_tour(match_id))); create policy selected_drives_write on public.selected_drives for all to authenticated using(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)) with check(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id));
create policy confirmations_read on public.match_confirmations for select to authenticated using(public.can_read_tour(public.match_tour(match_id))); create policy confirmations_insert_participant on public.match_confirmations for insert to authenticated with check(public.is_tour_organiser(public.match_tour(match_id)) or public.is_match_participant(match_id)); create policy confirmations_org_update on public.match_confirmations for update to authenticated using(public.is_tour_organiser(public.match_tour(match_id))) with check(public.is_tour_organiser(public.match_tour(match_id)));
create policy invitations_org_read on public.invitations for select to authenticated using(public.is_tour_organiser(tour_id)); create policy invitations_org_all on public.invitations for all to authenticated using(public.is_tour_organiser(tour_id)) with check(public.is_tour_organiser(tour_id)); create policy audit_org_read on public.audit_log for select to authenticated using(public.is_tour_organiser(tour_id));
